file.content:
const words = query.split(/\s+/).filter(Boolean);
const requiredLabel = $("#searchLabel").value.toLowerCase();
const exact = $("#exactPhrase").checked;
let visible = 0;
document.querySelectorAll(".bookmark-card").forEach((card) => {
  const fields = {
    title: card.querySelector("h2").textContent.toLowerCase(),
    description: card.querySelector(".bookmark-body > p:not(.saved-line):not(.match-reason)").textContent.toLowerCase(),
    address: card.querySelector(".source-line span:last-child").textContent.toLowerCase(),
    note: (card.dataset.note || "").toLowerCase()
  };
  const combined = Object.values(fields).join(" ");
  const wordMatch = !query || (exact ? combined.includes(query) : words.every((word) => combined.includes(word)));
  const labelsForCard = card.dataset.labels.split(",").map((label) => label.toLowerCase());
  const labelMatch = !requiredLabel || labelsForCard.includes(requiredLabel);
  const matches = card.dataset.archived !== "true" && wordMatch && labelMatch;
  card.hidden = !matches;
  if (matches) visible += 1;
  const reason = card.querySelector(".match-reason");
  if (reason) {
    const matchingField = Object.entries(fields).find(([name, value]) => name !== "title" && (exact ? value.includes(query) : words.length && words.every((word) => value.includes(word))));
    reason.textContent = matchingField ? `Matched the ${matchingField[0] === "note" ? "personal note" : matchingField[0]}` : "";
    reason.hidden = !query || !matchingField;
  }
});

