function showAdvancedLabelReady() {
  showAdvancedSearchA();
  const cards = [...document.querySelectorAll(".bookmark-card")];
  cards[1].dataset.note = "Natural shorelines shape attention; soft evening lighting can restore focus.";
  $("#advancedSearchPanel").hidden = false;
  $("#searchInput").value = "natural";
  applyAdvancedSearch();
}

function applyTypedAdvancedSearch() {
  const raw = $("#searchInput").value.trim();
  const labelToken = raw.match(/#([^\s"]+)/);
  const requestedLabel = labelToken
    ? existingLabels.find((label) => label.toLowerCase() === labelToken[1].toLowerCase()) || ""
    : "";
  const phrases = [...raw.matchAll(/"([^"]+)"/g)].map((match) => match[1].toLowerCase());
  const looseText = raw.replace(/"[^"]*"/g, " ").replace(/#[^\s"]*/g, " ").trim().toLowerCase();
  const words = looseText.split(/\s+/).filter(Boolean);
  let visible = 0;
  document.querySelectorAll(".bookmark-card").forEach((card) => {
    const fields = [
      card.querySelector("h2").textContent,
      card.querySelector(".bookmark-body > p:not(.saved-line):not(.match-reason)").textContent,
      card.querySelector(".source-line span:last-child").textContent,
      card.dataset.note || ""
    ].map((value) => value.toLowerCase());
    const combined = fields.join(" ");
    const textMatch = words.every((word) => combined.includes(word)) && phrases.every((phrase) => combined.includes(phrase));
    const labelMatch = !requestedLabel || card.dataset.labels.split(",").some((label) => label.toLowerCase() === requestedLabel.toLowerCase());
    const matches = card.dataset.archived !== "true" && textMatch && labelMatch;
    card.hidden = !matches;
    if (matches) visible += 1;
  });
  $("#libraryTitle").textContent = raw ? "Search results" : "All bookmarks";
  $(".result-count").textContent = `${visible} ${visible === 1 ? "bookmark" : "bookmarks"}`;
  $("#clearSearch").hidden = !raw;
  const chips = $("#searchFilterChips");
  const chipLabels = [];
  if (requestedLabel) chipLabels.push(`Within: ${requestedLabel}`);
  phrases.forEach((phrase) => chipLabels.push(`Exact: “${phrase}”`));
  chips.innerHTML = chipLabels.map((chip) => `<span>${chip}</span>`).join("");
  chips.hidden = chipLabels.length === 0;
  const fragment = raw.match(/#([^\s"]*)$/);
  const suggestions = $("#typedLabelSuggestions");
  const matches = fragment
    ? existingLabels.filter((label) => label.toLowerCase().startsWith(fragment[1].toLowerCase()) && label.toLowerCase() !== fragment[1].toLowerCase())
    : [];
  suggestions.innerHTML = "";
  matches.forEach((label) => {
    const button = document.createElement("button");
    button.type = "button";
    button.innerHTML = `<strong># ${label}</strong><small>Search within this label</small>`;
    button.addEventListener("click", () => {
      $("#searchInput").value = raw.replace(/#[^\s"]*$/, `#${label}`);
      applyTypedAdvancedSearch();
      $("#searchInput").focus();
    });
    suggestions.appendChild(button);
  });
  suggestions.hidden = matches.length === 0;
}

function showAdvancedSearchB() {
  showSearchLibrary("a");
  const cards = [...document.querySelectorAll(".bookmark-card")];
  cards[1].dataset.note = "Natural shorelines shape attention; soft evening lighting can restore focus.";
  $("#searchHint").hidden = true;
  $("#typedSearchHelp").hidden = false;
  $("#searchInput").value = "natural #arch";
  $("#searchInput").addEventListener("input", applyTypedAdvancedSearch);

